      "trauma_points": [
        "Mother sacrificed herself to protect him from father (age 6)",
        "Sold to assassins' guild in exchange for liquor (age 9)",
        "First assassination: poisoning his father (age 12)",
        "Recaptured by slavers after master's death via cursed contract (age 25)"
      ],
      "psychological_legacy": {
        "core_belief": "Affection is a debt that demands repayment in suffering",
        "fatal_flaw": "Cannot recognize care disguised as cruelty"
      }
    },
    "worldbuilding": {
      "slavery_system": {
